const CONFIG = {
  sheets: {
    spreadsheet: 'PASTE_YOUR_GOOGLE_SHEET_URL_OR_ID_XXXXXX',  // ← full URL is fine
    inputsTab: 'Inputs',   // what to scrape (auto-created with examples on first run)
    videosTab: 'Videos',   // results (auto-created; one row per video, updated in place)
  },
  youtube: {
    defaultMaxResults: 10,      // per input row when column B is empty (1–50)
    searchOrder: 'relevance',   // relevance | date | viewCount | rating | title
    regionCode: '',             // optional 2-letter country for searches, e.g. 'IN'
    maxSearchesPerRun: 20,      // quota guard: each search costs 100 of your 10,000 daily units
  },
};

// ── validation ──
const problems = [];
let id = String(CONFIG.sheets.spreadsheet || '').trim();
const m = /\/spreadsheets\/d\/([A-Za-z0-9_-]+)/.exec(id);
if (m) id = m[1];
if (/XXXXXX/.test(id)) problems.push('sheets.spreadsheet is still the placeholder — paste your Google Sheet URL.');
else if (!/^[A-Za-z0-9_-]{25,}$/.test(id)) problems.push('sheets.spreadsheet must be a Google Sheet URL or its ID (the long part after /d/).');
for (const k of ['inputsTab', 'videosTab']) if (!String(CONFIG.sheets[k] || '').trim()) problems.push('sheets.' + k + ' is empty.');
if (CONFIG.sheets.inputsTab.trim().toLowerCase() === CONFIG.sheets.videosTab.trim().toLowerCase()) problems.push('inputsTab and videosTab must be different tabs.');
const y = CONFIG.youtube;
if (!Number.isInteger(y.defaultMaxResults) || y.defaultMaxResults < 1 || y.defaultMaxResults > 50) problems.push('youtube.defaultMaxResults must be 1–50.');
if (!['relevance', 'date', 'viewCount', 'rating', 'title'].includes(y.searchOrder)) problems.push('youtube.searchOrder must be relevance, date, viewCount, rating or title.');
if (y.regionCode && !/^[A-Za-z]{2}$/.test(y.regionCode)) problems.push('youtube.regionCode must be 2 letters (e.g. IN) or empty.');
if (!Number.isInteger(y.maxSearchesPerRun) || y.maxSearchesPerRun < 0 || y.maxSearchesPerRun > 90) problems.push('youtube.maxSearchesPerRun must be 0–90.');
if (problems.length) throw new Error('CONFIG needs attention → ' + problems.join(' • '));

const base = 'https://sheets.googleapis.com/v4/spreadsheets/' + id;
return [{ json: {
  ...CONFIG,
  sheets: { ...CONFIG.sheets, spreadsheetId: id, inputsTab: CONFIG.sheets.inputsTab.trim(), videosTab: CONFIG.sheets.videosTab.trim() },
  urls: {
    sheetsBase: base,
    meta: base + '?fields=' + encodeURIComponent('properties.title,sheets.properties(sheetId,title,gridProperties)'),
    youtube: 'https://www.googleapis.com/youtube/v3',
  },
} }];

