const INPUT_HEADER = ['Input', 'Max Results', 'Enabled', 'Last Run', 'Status', 'Videos Found'];
const VIDEO_HEADER = ['Video ID', 'Video URL', 'Title', 'Channel Name', 'Channel ID', 'Description', 'Publish Date', 'View Count', 'Like Count', 'Comment Count', 'Duration', 'Tags', 'Thumbnail URL', 'Source Input', 'Last Updated', 'First Seen'];
const q = t => "'" + String(t).replace(/'/g, "''") + "'";   // A1-notation tab quoting


const cfg = $('CONFIG').first().json;
const r = readHttp($input.first());
if (!r.ok) {
  throw new Error('Could not open the Google Sheet. ' + r.message + googleHint(r, 'Google Sheets API') +
    (r.status === 404 || r.status === 403 ? ' The sheet must be owned by, or shared (Editor) with, the Google account connected in n8n.' : ''));
}
const sheets = (r.body.sheets || []).map(s => s.properties);
const find = t => sheets.find(s => String(s.title).trim().toLowerCase() === t.toLowerCase());
const tabNames = {}, requests = [], created = [];
let nextId = 700000000 + Math.floor(Math.random() * 100000000);
const cell = v => (typeof v === 'number' ? { userEnteredValue: { numberValue: v } } : { userEnteredValue: { stringValue: String(v) } });
const boldRow = vals => ({ values: vals.map(v => ({ ...cell(v), userEnteredFormat: { textFormat: { bold: true } } })) });
const plainRow = vals => ({ values: vals.map(cell) });

for (const [key, wanted, rows] of [
  ['inputs', cfg.sheets.inputsTab, [boldRow(INPUT_HEADER), plainRow(['n8n automation tutorial', 5, 'TRUE']), plainRow(['https://www.youtube.com/@n8n-io', 5, 'TRUE'])]],
  ['videos', cfg.sheets.videosTab, [boldRow(VIDEO_HEADER)]],
]) {
  const existing = find(wanted);
  if (existing) { tabNames[key] = existing.title; continue; }
  const sheetId = nextId++;
  tabNames[key] = wanted;
  created.push(wanted);
  requests.push({ addSheet: { properties: { sheetId, title: wanted, gridProperties: { frozenRowCount: 1 } } } });
  requests.push({ appendCells: { sheetId, rows, fields: 'userEnteredValue,userEnteredFormat.textFormat.bold' } });
}
const ranges = [q(tabNames.inputs) + '!A1:F5000', q(tabNames.videos) + '!A1:P1', q(tabNames.videos) + '!A2:A'];
const readUrl = cfg.urls.sheetsBase + '/values:batchGet?majorDimension=ROWS&valueRenderOption=FORMATTED_VALUE&' +
  ranges.map(x => 'ranges=' + encodeURIComponent(x)).join('&');
return [{ json: { needsSetup: requests.length > 0, requests, created, tabNames, readUrl, sheetTitle: r.body.properties ? r.body.properties.title : '' } }];


function googleHint(r, api) {
  const m = String(r.message || '');
  if (/accessNotConfigured|SERVICE_DISABLED|has not been used in project|is disabled/i.test(m))
