  if (r.status === 401) return ' → The Google credential is no longer authorised. Open the credential in n8n and click "Sign in with Google" again.';
  if (r.status === 403 && /insufficient|scope/i.test(m)) return ' → The Google credential lacks a scope. Reconnect it ("Sign in with Google") and tick every permission box.';
  if (r.status === 403) return ' → Permission denied. Make sure the signed-in Google account can edit this file/folder.';
  if (r.status === 404) return ' → Not found. Check the ID in CONFIG and that the signed-in Google account has access to it.';
