const INPUT_HEADER = ['Input', 'Max Results', 'Enabled', 'Last Run', 'Status', 'Videos Found'];
const VIDEO_HEADER = ['Video ID', 'Video URL', 'Title', 'Channel Name', 'Channel ID', 'Description', 'Publish Date', 'View Count', 'Like Count', 'Comment Count', 'Duration', 'Tags', 'Thumbnail URL', 'Source Input', 'Last Updated', 'First Seen'];
const q = t => "'" + String(t).replace(/'/g, "''") + "'";   // A1-notation tab quoting


const cfg = $('CONFIG').first().json;
const tabs = $('Plan Tabs').first().json.tabNames;
const r = readHttp($input.first());
if (!r.ok) throw new Error('Could not read the sheet tabs. ' + r.message + googleHint(r, 'Google Sheets API'));
const vr = (r.body && r.body.valueRanges) || [];
const inputRows = (vr[0] && vr[0].values) || [];
const videoHeader = ((vr[1] && vr[1].values) || [[]])[0] || [];
const idRows = (vr[2] && vr[2].values) || [];

if (videoHeader.length && String(videoHeader[0]).trim() !== VIDEO_HEADER[0]) {
  throw new Error('The "' + tabs.videos + '" tab has data that this workflow did not create (A1 = "' + videoHeader[0] + '"). Use an empty tab: rename that tab or set CONFIG.sheets.videosTab to a new name.');
}
const existing = {};
idRows.forEach((row, i) => { const v = String(row[0] || '').trim(); if (v && !existing[v]) existing[v] = i + 2; });

// ---- classify each input row ----
function classify(raw) {
  const s = raw.trim();
  if (/^@[\w.\-]{3,}$/.test(s)) return { type: 'channel', by: 'forHandle', value: s };
  // Manual URL parsing (the Code-node sandbox does not guarantee a global URL class).
  const um = /^(?:https?:\/\/)?((?:[a-z0-9-]+\.)*(?:youtube\.com|youtu\.be|youtube-nocookie\.com))(\/[^?#]*)?(?:\?([^#]*))?/i.exec(s);
  if (!um) return { type: 'search', value: s };
  const params = {};
  for (const kv of (um[3] || '').split('&')) { if (!kv) continue; const i = kv.indexOf('='); const k = decodeURIComponent(i < 0 ? kv : kv.slice(0, i)); if (!(k in params)) params[k] = i < 0 ? '' : decodeURIComponent(kv.slice(i + 1).replace(/\+/g, ' ')); }
  const u = { hostname: um[1].toLowerCase(), pathname: um[2] || '/', searchParams: { get: k => (k in params ? params[k] : null) } };
  const host = u.hostname.replace(/^(www|m|music)\./, '');
  const path = u.pathname, v = u.searchParams.get('v'), list = u.searchParams.get('list');
  let m;
  if (host === 'youtu.be' && (m = /^\/([\w-]{11})/.exec(path))) return { type: 'video', value: m[1] };
  if (v && /^[\w-]{11}$/.test(v)) return { type: 'video', value: v };
  if ((m = /^\/(shorts|live|embed|v)\/([\w-]{11})/.exec(path))) return { type: 'video', value: m[2] };
  if (list) return { type: 'playlist', value: list };
  if ((m = /^\/channel\/(UC[\w-]{22})/.exec(path))) return { type: 'channel', by: 'id', value: m[1] };
  if ((m = /^\/(@[^/?#]+)/.exec(path))) return { type: 'channel', by: 'forHandle', value: decodeURIComponent(m[1]) };
  if ((m = /^\/user\/([^/?#]+)/.exec(path))) return { type: 'channel', by: 'forUsername', value: decodeURIComponent(m[1]) };
  if (/^\/c\//.test(path)) return { type: 'unsupported', value: s, reason: 'Legacy /c/ channel URLs cannot be resolved by the YouTube API — open the channel and paste its @handle URL instead.' };
  return { type: 'unsupported', value: s, reason: 'Unrecognised YouTube URL. Use a video, playlist, @handle/channel URL, or plain search words.' };
}

const Y = cfg.urls.youtube, yt = cfg.youtube;
const hasHeader = String((inputRows[0] || [])[0] || '').trim().toLowerCase() === 'input';
const jobs = [], resolveReqs = [], listReqs = [], videoRefs = [];
let searches = 0;
inputRows.forEach((row, i) => {
  if (hasHeader && i === 0) return;
  const input = String(row[0] || '').trim();
  if (!input) return;
  const enabled = String(row[2] === undefined ? '' : row[2]).trim().toLowerCase();
  if (['false', 'no', 'n', '0', 'off', 'disabled'].includes(enabled)) return;
  const n = parseInt(String(row[1] || '').replace(/[^0-9]/g, ''), 10);
  const max = Math.min(50, Math.max(1, Number.isFinite(n) && n > 0 ? n : yt.defaultMaxResults));
  const c = classify(input);
  const job = { idx: jobs.length, row: i + 1, input, type: c.type, max, error: '', note: '', found: 0 };
  jobs.push(job);
  if (c.type === 'unsupported') { job.error = c.reason; return; }
  if (c.type === 'video') { videoRefs.push({ id: c.value, jobIdx: job.idx }); return; }
  if (c.type === 'playlist') { listReqs.push({ jobIdx: job.idx, kind: 'playlist', url: Y + '/playlistItems?part=contentDetails&maxResults=' + max + '&playlistId=' + encodeURIComponent(c.value) }); return; }
  if (c.type === 'channel' && c.by === 'id') { listReqs.push({ jobIdx: job.idx, kind: 'channel', url: Y + '/playlistItems?part=contentDetails&maxResults=' + max + '&playlistId=' + encodeURIComponent('UU' + c.value.slice(2)) }); return; }
  if (c.type === 'channel') { resolveReqs.push({ jobIdx: job.idx, url: Y + '/channels?part=contentDetails&' + c.by + '=' + encodeURIComponent(c.value) }); return; }
  if (searches >= yt.maxSearchesPerRun) { job.error = 'Skipped — CONFIG.youtube.maxSearchesPerRun (' + yt.maxSearchesPerRun + ') reached for this run.'; return; }
  searches++;
  listReqs.push({ jobIdx: job.idx, kind: 'search', url: Y + '/search?part=id&type=video&maxResults=' + max + '&order=' + yt.searchOrder +
    (yt.regionCode ? '&regionCode=' + yt.regionCode.toUpperCase() : '') + '&q=' + encodeURIComponent(input) });
});

return [{ json: {
